/**
 * מתרגם את מה ש-Claude חילץ לפעולות: שינויי לו"ז, הגשות, והודעות.
 * כללים: מופע לא מפורש = המופע הבא אחרי שליחת המייל. קבוצה אחרת = לא נוגעים. ספק = לאישור באפליקציה.
 */
function interpret(result, e, data, L) {
  const out = { changes: [], events: [], inbox: [] };
  if (!result || !result.relevant) return out;
  const ref = e.messageId;
  const src = `${e.from} · ${e.subject}`;
  result.items.forEach((it, i) => {
    const course = data.courses.find((c) => c.id === it.course_id);
    const name = course ? course.short || course.name : "קורס לא מזוהה";
    if (!course) {
      out.inbox.push({ kind: "alert", title: "מייל לבירור – לא זוהה קורס", body: `${result.summary}\n\n${src}`, dedupe_key: `mail-unknown-${ref}-${i}` });
      return;
    }
    if (it.is_my_group === "no") {
      out.inbox.push({ kind: "alert", title: `${name}: שינוי בקבוצה אחרת (לא עודכן)`, body: `${it.note || result.summary}\n\n${src}`, dedupe_key: `mail-other-${ref}-${i}` });
      return;
    }
    if (it.type === "deadline" || it.type === "exam_change") {
      const date = it.new_date || it.date;
      if (!date) { out.inbox.push({ kind: "alert", title: `${name}: ${it.title || "הגשה/מבחן"} – בלי תאריך`, body: `${it.note}\n\n${src}`, dedupe_key: `mail-nodate-${ref}-${i}` }); return; }
      out.events.push({ source: "email", external_id: `${ref}#${i}`, course_id: course.id, kind: it.type === "exam_change" ? "exam" : "submission", title: it.title || result.summary, date, time: it.end_time || it.start_time || null });
      out.inbox.push({ kind: "alert", title: `${name}: ${it.title || "מועד"} – ${L.fmtLong(date)}`, body: `${it.note || result.summary}\n\n${src}`, dedupe_key: `mail-dl-${ref}-${i}` });
      return;
    }
    if (!["cancelled", "extra", "moved"].includes(it.type)) return;
    let sessionType = it.session_type;
    if (sessionType === "none") sessionType = (course.sessions || [])[0] && course.sessions[0].type;
    const hasType = (course.sessions || []).some((s) => s.type === sessionType);
    let date = it.date;
    let resolvedNote = "";
    if (!date && it.type !== "extra" && hasType) {
      const next = L.nextSessionAfter(course, sessionType, data.semester, e.date);
      if (next) { date = next.date; resolvedNote = ` (חושב: המופע הבא אחרי שליחת המייל)`; }
    }
    if (it.type === "extra" && !date) date = it.new_date;
    let review = it.confidence === "low" || !hasType || !date;
    if (it.is_my_group === "unknown" && sessionType !== "lecture") review = true;
    if (date && (it.type === "cancelled" || it.type === "moved") && hasType) {
      const s = course.sessions.find((x) => x.type === sessionType);
      const occ = L.sessionOccurrences({ ...s, cancelled: [] }, data.semester, null);
      if (!occ.some((o) => o.date === date)) review = true; // התאריך לא נופל על מופע אמיתי
    }
    if (!date) {
      out.inbox.push({ kind: "alert", title: `${name}: שינוי בלי תאריך ברור`, body: `${it.note || result.summary}\n\n${src}`, dedupe_key: `mail-nodate-${ref}-${i}` });
      return;
    }
    const label = `${L.SESSION_LABEL[sessionType] || ""}`;
    const verb = { cancelled: "בוטל/ה", extra: "השלמה", moved: it.new_date && it.new_date !== date ? "הוזז/ה" : "שינוי מיקום" }[it.type];
    const title = `${name} – ${label} ${L.fmtLong(date)}: ${verb}${it.new_date && it.new_date !== date ? ` ל-${L.fmtLong(it.new_date)}` : ""}`;
    out.changes.push({
      course_id: course.id, session_type: sessionType, change: it.type, date,
      new_date: it.new_date || null, start_time: it.start_time || null, end_time: it.end_time || null,
      location: it.location || null, note: (it.note || "").slice(0, 200) + resolvedNote,
      source_ref: ref, confidence: it.confidence, status: review ? "needs_review" : "applied",
      _inbox: { kind: review ? "review" : "alert", title: review ? `לאשר? ${title}` : title, body: `${it.note || result.summary}${resolvedNote}\n\n${src}`, dedupe_key: `mail-ch-${ref}-${i}` },
    });
  });
  return out;
}

/**
 * חילוץ לפי כללים, בלי מודל ובלי עלות. מחזיר אובייקט באותה צורה כמו תשובת Claude,
 * כך ש-interpret עובד עליו בלי שינוי. הזהירות כאן גבוהה: ספק = confidence "low" = לאישור באפליקציה.
 */
const RE_CANCEL = /(בוטל|מבוטל|ביטול|לא תתקיים|לא יתקיים|cancel)/i;
const RE_EXTRA = /(השלמה|make-?up)/i;
const RE_MOVED = /(הוזז|הזזה|נדחה|דחייה|שינוי מועד|שינוי חדר|מעבר לזום|בזום|rescheduled|moved|postpone|room change|zoom)/i;
const RE_DEADLINE = /(הגשה|להגיש|בוחן|מבחן|deadline|due)/i;

function findDates(text, mailDate) {
  const out = [];
  const re = /(\d{1,2})[./](\d{1,2})(?:[./](\d{2,4}))?/g;
  let m;
  while ((m = re.exec(text))) {
    const d = +m[1], mo = +m[2];
    if (d < 1 || d > 31 || mo < 1 || mo > 12) continue;
    let y = m[3] ? +m[3] : mailDate.getFullYear();
    if (y < 100) y += 2000;
    if (!m[3] && new Date(y, mo - 1, d) < new Date(mailDate.getTime() - 60 * 86400000)) y += 1;
    out.push(`${y}-${String(mo).padStart(2, "0")}-${String(d).padStart(2, "0")}`);
  }
  return out;
}

function ruleExtract(e, data, L) {
  const text = `${e.subject}\n${e.text}`.slice(0, 4000);
  const low = text.toLowerCase();
  const hits = data.courses.filter((c) => [c.name, c.short, c.code].filter((x) => x && String(x).length >= 3).some((x) => low.includes(String(x).toLowerCase())));
  const course = hits.length === 1 ? hits[0] : null;
  let type = null;
  if (RE_CANCEL.test(text)) type = "cancelled";
  else if (RE_EXTRA.test(text)) type = "extra";
  else if (RE_MOVED.test(text)) type = "moved";
  else if (RE_DEADLINE.test(text)) type = /בוחן|מבחן/.test(text) ? "exam_change" : "deadline";
  if (!type) return { relevant: false, summary: "", items: [] };
  const session = /(תרגול|תרגיל|tutorial)/i.test(text) ? "tutorial" : /(מעבדה|סדנה|workshop)/i.test(text) ? "workshop" : /(הרצאה|lecture)/i.test(text) ? "lecture" : "none";
  const dates = findDates(text, e.date);
  const times = [...text.matchAll(/\b([01]?\d|2[0-3]):([0-5]\d)\b/g)].map((m) => `${m[1].padStart(2, "0")}:${m[2]}`);
  const zoom = /(זום|zoom)/i.test(text);
  const sure = !!(course && dates.length && type);
  return {
    relevant: true,
    summary: e.subject.slice(0, 120),
    items: [{
      course_id: course ? course.id : "unknown",
      type,
      session_type: session,
      date: dates[0] || "",
      new_date: type === "moved" || type === "extra" ? (dates[1] || "") : "",
      start_time: times[0] || "",
      end_time: times[1] || "",
      location: zoom ? "זום" : "",
      title: type === "deadline" || type === "exam_change" ? e.subject.slice(0, 80) : "",
      is_my_group: "unknown",
      confidence: sure ? "high" : "low",
      note: "זוהה אוטומטית לפי כללים (בלי מודל). כדאי לוודא מול המייל המקורי.",
    }],
  };
}

module.exports = { emailFields, isCandidate, buildRequest, ANTHROPIC_HEADERS, readResponse, interpret, schema, ruleExtract };

return module.exports; })();

const Briefs = (function () { const module = { exports: {} }; const exports = module.exports;
// תדריך בוקר, תדריך שבועי ותזכורות – נכתבים ל-inbox ומוצגים באפליקציה.

function openDeadlines(ctx, L) {
  return ctx.data.deadlines
    .filter((d) => !d.moedB)
    .map((d) => ({ ...d, id: L.deadlineId(d) }))
    .filter((d) => !(ctx.state.done || {})[d.id]);
}
const cname = (ctx, id) => { const c = ctx.data.courses.find((x) => x.id === id); return c ? c.short || c.name : "כללי"; };
const daysText = (n) => (n === 0 ? "היום" : n === 1 ? "מחר" : n < 0 ? "באיחור" : `בעוד ${n} ימים`);

function sessionsToday(ctx, L, now) {
  return L.sessionsOnDate(ctx.data.courses, ctx.data.semester, L.iso(now))
    .map((s) => `• ${s.start}–${s.end} ${s.course.short} · ${L.SESSION_LABEL[s.session.type]} – ${s.extra ? s.note : s.session.location || ""}`);
}

function paceLines(ctx, L, now) {
  return ctx.data.courses
    .map((c) => ({ c, p: L.paceStatus(c, ctx.data.semester, now, ctx.state.seen || {}) }))
    .filter((x) => x.p.behind > 0)
    .map((x) => `• ${x.c.short}: מאחור ב-${x.p.behind}${x.p.items.some((i) => i.urgent) ? " (יש דחוף)" : ""}`);
}

function recentChanges(ctx, L, sinceMs) {
  const since = Date.now() - sinceMs;
  const ev = ctx.events.filter((e) => new Date(e.created_at).getTime() > since).map((e) => `• חדש: ${cname(ctx, e.course_id)} – ${e.title} (${L.fmt(e.date)})`);
  const ch = ctx.changes.filter((c) => new Date(c.created_at).getTime() > since)
    .map((c) => `• ${cname(ctx, c.course_id)} ${L.SESSION_LABEL[c.session_type]} ${L.fmt(c.date)}: ${{ cancelled: "בוטל", extra: "השלמה", moved: "שינוי" }[c.change]}${c.status === "needs_review" ? " (מחכה לאישור שלך)" : ""}`);
  return [...ev, ...ch];
}

function dailyBrief(ctx, L, now) {
  const tiers = L.prioritize(openDeadlines(ctx, L), now);
  const urgent = [...tiers[0].items, ...tiers[1].items, ...tiers[2].items].slice(0, 5)
    .map((t) => `• ${cname(ctx, t.courseId)} – ${t.title} · ${L.fmt(t.date)} (${daysText(t.days)})${t.flag ? " · " + t.flag : ""}`);
  const sessions = sessionsToday(ctx, L, now);
  const pace = paceLines(ctx, L, now);
  const news = recentChanges(ctx, L, 26 * 3600 * 1000);
  const parts = [
    `📅 היום:\n${sessions.length ? sessions.join("\n") : "אין שיעורים"}`,
    `🔥 הכי דחוף:\n${urgent.length ? urgent.join("\n") : "אין משימות ב-10 הימים הקרובים"}`,
  ];
  if (pace.length) parts.push(`⏱️ קצב:\n${pace.join("\n")}`);
  if (news.length) parts.push(`🆕 מאז אתמול:\n${news.join("\n")}`);
  return { kind: "brief", title: `תדריך בוקר – ${L.fmtLong(L.iso(now))}`, body: parts.join("\n\n"), dedupe_key: `brief-${L.iso(now)}` };
}

function weeklyBrief(ctx, L, now) {
  const dl = openDeadlines(ctx, L).map((d) => ({ ...d, days: L.daysUntil(d.date, now) }));
  const subs = dl.filter((d) => d.kind !== "exam" && d.days >= 0 && d.days <= 14);
  const exams = dl.filter((d) => d.kind === "exam" && d.days >= 0 && d.days <= 21);
  const week = L.weekLoad(ctx.data.deadlines, ctx.data.semester, now).find((w) => w.current);
  const thisWeek = dl.filter((d) => d.days >= 0 && d.days <= 6);
  const load = !week ? "" : week.load >= 40 ? "שבוע עמוס" : week.load > 0 ? "שבוע בינוני" : "שבוע רגוע";
  const head = `${load ? load + ": " : ""}${thisWeek.length ? `${thisWeek.length} הגשות/מבחנים השבוע. הכי חשוב: ${cname(ctx, thisWeek.sort((a, b) => (b.weight || 0) - (a.weight || 0))[0].courseId)} – ${thisWeek[0].title}` : "אין הגשות השבוע"}`;
  const fmtD = (d) => `• ${L.fmt(d.date)} ${cname(ctx, d.courseId)} – ${d.title}${d.weight ? ` (${d.weight}%)` : ""} · ${daysText(d.days)}`;
  const news = recentChanges(ctx, L, 7 * 24 * 3600 * 1000);
  const plan = subs.slice(0, 5).map((d, i) => `${i + 1}. ${cname(ctx, d.courseId)} – ${d.title}`);
  const parts = [
    `השבוע במשפט: ${head}`,
    `📌 הגשות ב-14 הימים הקרובים:\n${subs.length ? subs.map(fmtD).join("\n") : "אין"}`,
    `📝 מבחנים ב-21 הימים הקרובים:\n${exams.length ? exams.map(fmtD).join("\n") : "אין"}`,
  ];
  if (news.length) parts.push(`🆕 השבוע שעבר:\n${news.join("\n")}`);
  if (plan.length) parts.push(`🧱 סדר מומלץ לבלוקי העבודה:\n${plan.join("\n")}`);
  return { kind: "weekly", title: `תדריך שבועי – ${L.fmtLong(L.iso(now))}`, body: parts.join("\n\n"), dedupe_key: `weekly-${L.iso(now)}` };
}

function reminders(ctx, L, now) {
  const out = [];
  const today = L.iso(now);
  const tomorrow = L.iso(L.addDays(now, 1));
  for (const d of openDeadlines(ctx, L)) {
    const days = L.daysUntil(d.date, now);
    if (d.kind !== "exam" && days === 1) out.push({ kind: "reminder", title: `מחר: ${cname(ctx, d.courseId)} – ${d.title}${d.time ? " עד " + d.time : ""}`, body: d.weight ? `${d.weight}% מהציון` : "", dedupe_key: `rem-1d-${d.id}` });
    if (d.kind !== "exam" && days === 3 && (d.weight || 0) >= 10) out.push({ kind: "reminder", title: `עוד 3 ימים: ${cname(ctx, d.courseId)} – ${d.title}`, body: `${d.weight}% מהציון. כדאי לשריין זמן.`, dedupe_key: `rem-3d-${d.id}` });
    if (d.kind === "exam") {
      const prep = L.iso(L.addDays(L.parseDate(d.date), -L.examPrepDays(d.weight)));
      if (prep === today) out.push({ kind: "reminder", title: `להתחיל ללמוד: ${cname(ctx, d.courseId)} – ${d.title}`, body: `המבחן ב-${L.fmtLong(d.date)} (${d.weight}%). נשארו ${days} ימים.`, dedupe_key: `rem-prep-${d.id}` });
    }
  }
  // הרצאה שלא ראית לפני תרגול של מחר
  for (const c of ctx.data.courses) {
    const p = L.paceStatus(c, ctx.data.semester, now, ctx.state.seen || {});
    const tut = p.pace.tutorial && p.pace.tutorial.next;
    if (tut && tut.date === tomorrow) {
      const unseen = p.items.filter((i) => i.type === "lecture" && !i.seen).map((i) => i.label);
      if (unseen.length) out.push({ kind: "reminder", title: `${c.short}: תרגול מחר, ועוד לא ראית ${unseen.slice(-2).join(", ")}`, body: `התרגול ב-${tut.start}, ${tut.location || ""}`, dedupe_key: `rem-lec-${c.id}-${tomorrow}` });
    }
  }
  return out;
}

module.exports = { dailyBrief, weeklyBrief, reminders };

return module.exports; })();

const ENV = { url: $env.SUPABASE_URL, key: $env.SUPABASE_SERVICE_KEY, user: $env.USER_ID };
if (!ENV.url || !ENV.key || !ENV.user) throw new Error("חסרים SUPABASE_URL / SUPABASE_SERVICE_KEY / USER_ID ב-automations/.env");
const http = (o) => this.helpers.httpRequest(o);
const supa = Common.makeSupa(http, ENV.url, ENV.key);
const now = new Date();
const withUser = (rows) => rows.map((r) => ({ ...r, user_id: ENV.user }));
async function postInbox(items) { return supa.upsert("inbox", withUser(items), "user_id,dedupe_key", "ignore"); }

// ---------- reminders ----------
const ctx = await Common.loadContext(supa, ENV.user, L);
const items = Briefs.reminders(ctx, L, now);
const saved = await postInbox(items);
return [{ json: { candidates: items.length, saved: saved.length } }];
